const input = $input.first().json;
const now = new Date();
const taskId = input.task_id || now.toISOString().slice(0, 10).replace(/-/g, '') + '-plan';

const rawEstimatedHours = Number(input.estimated_hours) || 12;
const paddedHours = Math.round(rawEstimatedHours * 1.25 * 10) / 10;
const daysUntilDue = Number(input.days_until_due) || 5;
const effectiveDays = Math.max(1, daysUntilDue - 1);
const dailyAvailableHours = Number(input.daily_available_hours) || 3;

const totalAvailableHours = effectiveDays * dailyAvailableHours;
const overloadDetected = paddedHours > totalAvailableHours;
const deficitHours = overloadDetected ? Math.round((paddedHours - totalAvailableHours) * 10) / 10 : 0;

return [
  {
    json: {
      task_id: taskId,
      current_date_ist: now.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata' }),
      assignments_list: input.assignments || input.query || input.chatInput || 'AI Agent Project (Weight: 30%, Due in 5 days)',
      raw_estimated_hours: rawEstimatedHours,
      padded_hours_with_25_pct_buffer: paddedHours,
      days_until_due: daysUntilDue,
      effective_work_days_after_24h_buffer: effectiveDays,
      total_available_hours: totalAvailableHours,
      overload_detected: overloadDetected,
      deficit_hours: deficitHours,
      instructor_email: input.instructor_email || 'instructor@example.com',
      plan_filename: `${taskId}-schedule.md`
    }
  }
];

